/** Generate built-in CSS from the same defaults used by editor/API validation. */
import { readFileSync, writeFileSync } from "node:fs";
const defaults = JSON.parse(
  readFileSync(new URL("../packages/core/src/appearance-defaults.json", import.meta.url)),
);
const css =
  "/* Generated by scripts/generate-theme-tokens.mjs. Edit appearance-defaults.json. */\n" +
  Object.entries(defaults)
    .map(
      ([mode, tokens]) =>
        `${mode === "light" ? ":root,\n" : ""}[data-theme="${mode}"] {\n${Object.entries(tokens)
          .map(([key, value]) => `  ${key}: ${value};`)
          .join("\n")}\n}\n`,
    )
    .join("\n");
const destination = new URL("../apps/dashboard/src/styles/theme-tokens.css", import.meta.url);
if (process.argv.includes("--check")) {
  if (readFileSync(destination, "utf8") !== css)
    throw new Error("Theme CSS is stale; run node scripts/generate-theme-tokens.mjs");
} else writeFileSync(destination, css);
